import argparse,csv,hashlib,json,subprocess,sys,tempfile,time
from pathlib import Path
parser=argparse.ArgumentParser();parser.add_argument('--source-root',required=True,type=Path);parser.add_argument('--output-root',required=True,type=Path);a=parser.parse_args();source=a.source_root.resolve();base=a.output_root.resolve();base.mkdir(parents=True,exist_ok=False);state=base/'state';records=[]
def hashes():return {str(p.relative_to(state)):hashlib.sha256(p.read_bytes()).hexdigest() for p in state.rglob('*') if p.is_file()}
def invoke(name,argv,forbid=False):
 code='import sys,json\nfrom unittest.mock import patch\nfrom tools.vnext_company import main\n'
 if forbid:
  code+='from vnext import historical_auditor_case as h,c04_registration_successor as c,calculator\nblocked={h.prepare_historical_auditor_year_case.__code__,c.prepare_c04_registration_case.__code__,calculator.calculate_metric.__code__,calculator.calculate_observation_metric.__code__}\ndef guard(frame,event,arg):\n if event=="call" and frame.f_code in blocked:raise AssertionError("Stable repeat/read cannot prepare or calculate")\nsys.setprofile(guard)\n'
 code+='with patch("socket.socket.connect",side_effect=AssertionError("No network")):\n raise SystemExit(main(json.loads(sys.argv[1])))'
 t=time.monotonic();p=subprocess.run([sys.executable,'-B','-c',code,json.dumps(argv)],capture_output=True,text=True);r={'name':name,'seconds':time.monotonic()-t,'exit':p.returncode,'arguments':argv,'stdout':p.stdout,'stderr':p.stderr};records.append(r);(base/(name+'.json')).write_text(json.dumps(r,indent=2)+'\n');print(name,r['seconds'],p.returncode,flush=True);assert p.returncode==0 and not p.stderr,r;return json.loads(p.stdout)
args=['run','--company','ford_motor_company','--period','fiscal-years','--fiscal-year-start','2022','--fiscal-year-end','2022','--metric','C04','--source-root',str(source),'--work-dir',str(state),'--output-dir',str(base/'runs')]
first=invoke('fresh-actual-source',args);assert first['metrics'][0]['status']=='CANDIDATE_READY';protected={p:h for p,h in hashes().items() if '/results/' in p}
again=invoke('forbidden-repeat',args,True);assert not again['metrics'][0]['calculation_performed'] and not again['metrics'][0]['new_candidate_created'];assert all(hashes().get(p)==h for p,h in protected.items())
before=hashes();out=base/'read';invoke('independent-read',['results','--company','ford_motor_company','--state-root',str(state),'--output-root',str(out)],True);assert before==hashes();rows=list(csv.DictReader((out/'metrics_matrix.csv').open()));assert len(rows)==1;row=rows[0];assert row['metric_id']=='C04' and row['value']=='0' and row['period_start']=='2022-01-01' and row['period_end']=='2022-12-31' and row['cik']=='37996' and row['result_id'].startswith('sha256:0ec6c7d6'),row
summary={'state_root':str(state),'records':records,'row':row,'protected_result_files':len(protected),'read_state_files_unchanged':len(before),'new_calls':[0,0,0]};(base/'summary.json').write_text(json.dumps(summary,indent=2)+'\n');print('Real selected C04 zero and exact identity retained; no new calls')
